@push('scripts')<script>(function(){var agencyGroups=@json($advertisingAgencyGroups),projects=@json($projects),target=document.getElementById('target-type'),action=document.getElementById('action-type'),agencyName=document.getElementById('agency-name'),agency=document.getElementById('agency-id'),project=document.getElementById('project-id'),system=document.getElementById('website-system-id'),reason=document.querySelector('[name="reason"]'),reasonLabel=document.getElementById('reason-label'),operator=document.getElementById('transfer-operator');function fields(){var type=target.value;document.querySelectorAll('.account-field').forEach(function(el){el.style.display=type==='account'?'block':'none';el.querySelectorAll('input,select').forEach(function(i){i.required=type==='account'})});document.querySelectorAll('.store-field').forEach(function(el){el.style.display=type==='store'?'block':'none';el.querySelectorAll('input,select').forEach(function(i){i.required=type==='store'})});if(type!=='account')agency.disabled=true;if(type!=='store')system.disabled=true}function fillAgency(){var list=agencyGroups[agencyName.value]||[];agency.innerHTML='<option value="">请选择社媒</option>';list.forEach(function(x){agency.add(new Option(x.media,x.key))});agency.disabled=target.value!=='account'||!list.length}function fillSystems(){var selected=projects.find(function(x){return String(x.id)===String(project.value)}),list=selected?selected.website_systems:[];system.innerHTML='<option value="">请选择建站系统</option>';list.forEach(function(x){system.add(new Option(x.name,x.id))});system.disabled=target.value!=='store'||!list.length}function reasonText(){var t=action.value==='transfer'?'转让理由':action.value==='discard'?'弃用理由':'理由';reasonLabel.textContent=t+' *';reason.placeholder='请填写'+t}target.addEventListener('change',function(){fields();fillAgency();fillSystems()});agencyName.addEventListener('change',fillAgency);project.addEventListener('change',fillSystems);action.addEventListener('change',reasonText);fields();fillSystems();reasonText();if(operator)operator.addEventListener('change',function(){location.href=this.dataset.url+'?operator_user_id='+encodeURIComponent(this.value)});})();</script>@endpush
